import {readFileSync} from 'node:fs';import {createRequire} from 'node:module';
const require=createRequire(import.meta.url),{parse}=require('@babel/parser');
const sourceUrl=file=>new URL('../../'+file,import.meta.url);
export const sourceText=file=>readFileSync(sourceUrl(file),'utf8');
export const actualModule=file=>import(sourceUrl(file));
export function realUiHelpers(){const source=sourceText('src/app/(identity)/cuenta/participant-kyc-capture.js'),ast=parse(source,{sourceType:'module',plugins:['jsx']}),wanted=new Set(['precommitFacialNotice','facialUuid','facialKeys','participantFacialModeValid','participantFacialModePatch','participantFacialStatusValid','participantFacialManualSuccessor']),parts=[];for(const row of ast.program.body){const n=row.type==='ExportNamedDeclaration'?row.declaration:row;if(n?.type==='VariableDeclaration'&&n.declarations.some(d=>wanted.has(d.id.name))||n?.type==='FunctionDeclaration'&&wanted.has(n.id.name))parts.push(source.slice(n.start,n.end));}return Function(parts.join('\n')+'\nreturn {participantFacialModeValid,participantFacialModePatch,participantFacialStatusValid,participantFacialManualSuccessor};')();}
export function realDeclaration(file,name){const source=sourceText(file),ast=parse(source,{sourceType:'module',plugins:['jsx']});let found;const walk=value=>{if(!value||typeof value!=='object')return;if(value.type==='FunctionDeclaration'&&value.id?.name===name)found=source.slice(value.start,value.end);if(value.type==='VariableDeclarator'&&value.id?.name===name)found='const '+source.slice(value.start,value.end)+';';for(const [key,child]of Object.entries(value)){if(['loc','extra','comments'].includes(key))continue;if(Array.isArray(child))child.forEach(walk);else if(child&&typeof child==='object')walk(child);}};walk(ast);if(!found)throw Error('Missing real declaration '+name);return found;}
